macro.movento_dbt.build_rls_dimension.macro_sql:
{% macro build_rls_dimension(cat_fichero_objeto, dimension_column, master_model) %}
WITH dimension_master AS (

    SELECT DISTINCT
        {{ dimension_column }}
    FROM {{ ref(master_model) }}
    WHERE {{ dimension_column }} IS NOT NULL

),

dimension_master_by_company AS (

    SELECT DISTINCT
        id_empresa,
        {{ dimension_column }}
    FROM {{ ref(master_model) }}
    WHERE id_empresa IS NOT NULL
      AND {{ dimension_column }} IS NOT NULL

),

base_attributes AS (

    SELECT
        id_usuario,
        id_valor_rls AS {{ dimension_column }}
    FROM {{ ref('int_seg__atributos_usuarios_exploded') }}
    WHERE cat_fichero_objeto = '{{ cat_fichero_objeto }}'

),

explicit_attributes AS (

    SELECT DISTINCT
        p.id_usuario,
        m.{{ dimension_column }}
    FROM base_attributes AS p
    INNER JOIN dimension_master AS m
        ON p.{{ dimension_column }} = m.{{ dimension_column }}

),

company_scope AS (

    SELECT DISTINCT
        id_usuario,
        id_empresa
    FROM {{ ref('gld_gen__rls_empresa') }}
    WHERE id_empresa IS NOT NULL

),

company_attributes AS (

    SELECT DISTINCT
        c.id_usuario,
        m.{{ dimension_column }}
    FROM company_scope AS c
    INNER JOIN dimension_master_by_company AS m
        ON c.id_empresa = m.id_empresa
    WHERE NOT EXISTS (
        SELECT 1
        FROM explicit_attributes AS e
        WHERE e.id_usuario = c.id_usuario
    )

),

unrestricted_attributes AS (

    SELECT DISTINCT
        u.id_usuario,
        m.{{ dimension_column }}
    FROM {{ ref('gld_gen__usuarios') }} AS u
    CROSS JOIN dimension_master AS m
    WHERE u.id_usuario IS NOT NULL
      AND NOT EXISTS (
          SELECT 1
          FROM company_scope AS c
          WHERE c.id_usuario = u.id_usuario
      )
      AND NOT EXISTS (
          SELECT 1
          FROM explicit_attributes AS e
          WHERE e.id_usuario = u.id_usuario
      )

),

rls_attributes AS (

    SELECT
        e.id_usuario,
        e.{{ dimension_column }}
    FROM explicit_attributes AS e

    UNION ALL

    SELECT
        f.id_usuario,
        f.{{ dimension_column }}
    FROM company_attributes AS f

    UNION ALL

    SELECT
        a.id_usuario,
        a.{{ dimension_column }}
    FROM unrestricted_attributes AS a

),

users AS (

    SELECT DISTINCT
        id_usuario,
        eml_persona AS correo,
        alias
    FROM {{ ref('gld_gen__usuarios') }}

)

SELECT DISTINCT
    e.id_usuario,
    u.correo,
    u.alias,
    e.{{ dimension_column }} AS {{ dimension_column }}
FROM rls_attributes AS e
LEFT JOIN users AS u
    ON e.id_usuario = u.id_usuario
{% endmacro %}

