macro.movento_dbt.fabric__expression_is_.macro_sql:
{% macro fabric__expression_is_true(model, expression, test_condition, group_by_columns, row_condition) -%}
with grouped_expression as (
    select
        {% if group_by_columns %}
        {% for group_by_column in group_by_columns -%}
        {{ group_by_column }} as col_{{ loop.index }},
        {% endfor -%}
        {% endif %}
        case when {{ expression }} then cast(1 as int) else cast(0 as int) end as expression
    from {{ model }}
     {%- if row_condition %}
    where
        {{ row_condition }}
    {% endif %}
    {% if group_by_columns %}
    group by
    {% for group_by_column in group_by_columns -%}
        {{ group_by_column }}{% if not loop.last %},{% endif %}
    {% endfor %}
    {% endif %}

),
validation_errors as (

    select
        *
    from
        grouped_expression
    where
        {% set normalized_test_condition = test_condition | lower | trim %}
        {% if normalized_test_condition == '= true' %}
        expression <> 1
        {% elif normalized_test_condition == '= false' %}
        expression <> 0
        {% else %}
        not(expression {{ test_condition }})
        {% endif %}

)

select *
from validation_errors


{% endmacro -%}

